// AI Uygulama Geliştirme ve Yayın cheat sheet. 10 konu.
import type { Topic } from './types'

export const aiUygulamaGiris: { q: string; a: string }[] = [
  { q: 'Bu başlık ne öğretir?', a: 'Yapay zekalı bir ürünü baştan sona kurmayı: kullanıcının gördüğü sohbet arayüzü, arkadaki sunucu, modelle konuşma, bellek, güvenlik, maliyet kontrolü, kalite ölçümü ve yayına alma. Önceki başlıklar parçaları öğretti; burası parçaları çalışan, güvenli ve ölçülebilir bir bütüne dönüştürüyor.' },
  { q: 'ChatGPT varken neden kendi uygulamamı yapayım?', a: 'Çünkü ChatGPT senin verini, müşterini ve iş akışını bilmez. Kendi uygulamanda model senin belgelerinle cevap verir, senin sistemlerinde işlem yapar, senin arayüzünde yaşar ve senin kurallarınla sınırlanır. Destek botu, belge asistanı, içerik üretici, veri çıkarma hattı: hepsi özelleştirilmiş uygulamadır.' },
  { q: 'Tipik mimari nasıl?', a: 'Üç katman: kullanıcının tarayıcısı ya da telefonu (arayüz), senin sunucun (backend) ve model sağlayıcısı (Claude, OpenAI). Arayüz asla modele doğrudan konuşmaz; her istek senin sunucundan geçer. Sunucu promptu kurar, belgeleri arar, araçları çalıştırır, kimliği ve kotayı kontrol eder, her şeyi kaydeder. API anahtarları yalnızca sunucuda durur.' },
  { q: 'Hangi teknolojiyle yapmalıyım?', a: 'JavaScript tarafında Next.js, Vercel AI SDK ve Supabase (Postgres artı pgvector) en yaygın yol; sohbet arayüzü hazır bileşenlerle saatler içinde kurulur. Python tarafında FastAPI, Anthropic SDK ve Postgres. Ekibin bildiği dili seç; makine öğrenmesi ağırlıklı projede Python, web ağırlıklıysa JavaScript.' },
  { q: 'En büyük riskler ne?', a: 'Beş tane: maliyet patlaması (kontrolsüz istek), prompt injection (belgeden ya da kullanıcıdan gelen gizli talimat), veri sızıntısı (kişisel verinin modele ya da loga gitmesi), güvenilmez çıktı (uydurma), ve sessiz kalite gerilemesi (prompt değişince kimse fark etmiyor). Her biri için bu bölümde bir önlem var.' },
  { q: 'Sohbet arayüzü şart mı?', a: 'Hayır, hatta çoğu zaman en iyi seçenek değil. "Özetle" butonu, satır içi öneri, formu otomatik doldurma gibi ürüne gömülü tek tık özellikler daha çok kullanılır ve daha ucuzdur. Sohbet, açık uçlu işler için; belirli işler için düğme.' },
  { q: 'Maliyeti nasıl kontrol altında tutarım?', a: 'Önce ölç: istek başına ortalama token ve model. Sonra bedava kazançlar: prompt önbelleği, gereksiz geçmişi kırpma, çıktı sınırı. Sonra küçük model yönlendirme ve toplu işler için Batch API. Üstüne kullanıcı başına kota ve günlük bütçe alarmı. Sağlayıcı panelinde sert limit her zaman açık.' },
  { q: 'Kaliteyi nasıl bilirim?', a: 'Hissiyatla değil ölçerek: 50-200 gerçek örnekten oluşan bir değerlendirme seti, otomatik puanlama (hakem model ya da şema kontrolü), her prompt ve model değişikliğinde çalışan test. Üretimde her isteğin izini (trace) tut, kullanıcı beğenmedi dediğinde o örneği sete ekle. Bu döngü ürünü zamanla iyileştirir.' },
  { q: 'Ön koşul ne?', a: 'Web geliştirme (React ve Node ya da Python backend), LLM API ve Prompt Mühendisliği. RAG ve Agent başlıkları özelliğe göre gerekir: belge asistanı için RAG, işlem yapan bot için Agent. Bu başlık bunların hepsini varsayıyor ve birleştiriyor.' },
  { q: 'İlk ürün ne kadar sürer?', a: 'Basit bir sohbet asistanı bir gün. Belgeleriyle konuşan, kimlik doğrulamalı, izlenen bir sürüm bir iki hafta. Kalite döngüsü (ölç, düzelt, tekrar) sürekli. Hazır Kalıplar konusundaki MVP planı ilk haftada ölçülebilir tek bir özellik çıkarmayı öneriyor.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Mimari → Sohbet Arayüzü → Backend → Durum ve Bellek → Güvenlik → Maliyet → Değerlendirme ve İzleme → Yayın → Hazır Kalıplar. İlk üç konu çalışan bir şey çıkarır; Güvenlik ve Maliyet olmadan yayına çıkma.' },
]

